require "config.php";$id=(int)($_GET["id"]??0);$r=$conexion->query("SELECT * FROM certificados WHERE id=$id LIMIT 1");if(!$r||!$r->num_rows)die("No encontrado.");$c=$r->fetch_assoc();$plantilla=__DIR__."/plantilla/certificado.jpg";$fuente=__DIR__."/fonts/DejaVuSans.ttf";$dir=__DIR__."/certificados";if(!is_dir($dir))mkdir($dir,0775,true);$im=imagecreatefromjpeg($plantilla);$col=imagecolorallocate($im,20,20,20);$txt=mb_strtoupper($c["nombre"]." ".$c["apellido"],"UTF-8");$tam=32;$b=imagettfbbox($tam,0,$fuente,$txt);$x=(imagesx($im)-($b[2]-$b[0]))/2;imagettftext($im,$tam,0,$x,500,$col,$fuente,$txt);$url="https://localhost/sistema_certificados_v7_correo/verificar.php?codigo=".urlencode($c["codigo"]);$q=@imagecreatefrompng("https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=".urlencode($url));if($q){$q=imagescale($q,150,150);imagecopy($im,$q,60,875,0,0,150,150);imagedestroy($q);}$f="certificado_".$c["codigo"].".jpg";imagejpeg($im,$dir."/".$f,95);imagedestroy($im);$s=$conexion->prepare("UPDATE certificados SET archivo=? WHERE id=?");$s->bind_param("si",$f,$id);$s->execute();?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Generado</title><style>body{text-align:center;font-family:Arial;background:#eee;padding:20px}img{max-width:95%}a{display:inline-block;margin:10px;padding:12px;background:#9b741c;color:#fff;text-decoration:none;border-radius:6px}</style></head><body><h2>Certificado generado</h2><img src="certificados/<?=htmlspecialchars($f)?>"><br><a href="certificados/<?=htmlspecialchars($f)?>" download>DESCARGAR</a><a href="index.php">MENÚ</a></body></html>